use WhatsUP\Core\Database;
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$db=Database::connection();$s=$db->prepare("SELECT id FROM users WHERE role='operator' LIMIT 1");$s->execute();$user=$s->fetchColumn();if(!$user){$s=$db->prepare("INSERT INTO users(name,email,password_hash,role,status,daily_limit,timezone,created_at,updated_at) VALUES('Demo Operator','demo@example.test',?,'operator','active',1000,'UTC',UTC_TIMESTAMP(),UTC_TIMESTAMP())");$s->execute([password_hash(bin2hex(random_bytes(16)),PASSWORD_DEFAULT)]);$user=(int)$db->lastInsertId();}
$contacts=[['Amara Mensah','+233201234567','opted_in'],['Kojo Boateng','+233241234568','opted_in'],['Esi Owusu','+233501234569','opted_in'],['Fictional Opt-out','+233271234560','unsubscribed']];foreach($contacts as [$name,$phone,$consent]){$s=$db->prepare('INSERT IGNORE INTO contacts(user_id,phone_e164,name,consent_status,consent_source,consented_at,unsubscribed_at,created_at,updated_at) VALUES(?,?,?,?,?,IF(?="opted_in",UTC_TIMESTAMP(),NULL),IF(?="unsubscribed",UTC_TIMESTAMP(),NULL),UTC_TIMESTAMP(),UTC_TIMESTAMP())');$s->execute([$user,$phone,$name,$consent,'Synthetic seed data',$consent,$consent]);}
$s=$db->prepare('INSERT IGNORE INTO groups(user_id,name,created_at,updated_at) VALUES(?,"Welcome list",UTC_TIMESTAMP(),UTC_TIMESTAMP())');$s->execute([$user]);$gid=(int)$db->query("SELECT id FROM groups WHERE user_id=".(int)$user." AND name='Welcome list'")->fetchColumn();$db->exec('INSERT IGNORE INTO group_contacts(user_id,group_id,contact_id,created_at) SELECT '.(int)$user.','.$gid.',id,UTC_TIMESTAMP() FROM contacts WHERE user_id='.(int)$user." AND consent_status='opted_in'");$db->prepare('INSERT IGNORE INTO templates(user_id,name,language,created_at,updated_at) VALUES(?,"Welcome note","en",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute([$user]);$tid=(int)$db->query('SELECT id FROM templates WHERE user_id='.(int)$user." AND name='Welcome note'")->fetchColumn();$db->prepare('INSERT IGNORE INTO template_parts(user_id,template_id,sequence_no,part_type,text_content,created_at) VALUES(?,?,1,"text","Hello! Thanks for joining our updates. Reply STOP at any time to opt out.",UTC_TIMESTAMP())')->execute([$user,$tid]);echo "Synthetic operator, fictional contacts, group and template ready. Demo operator has a random inaccessible password; create normal accounts via registration.\n";
